import{_ as l,a0 as i,w as d,s as a,I as n,x as t,a1 as o,A as r,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Linux有問必答：如何在VPS上安裝和訪問CentOS 7遠程桌面 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何在VPS上安裝和訪問CentOS 7遠程桌面 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何在VPS上安裝和訪問CentOS 7遠程桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何在VPS上安裝和訪問CentOS 7遠程桌面 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150323 Linux FAQs with Answers--How to install and access CentOS remote desktop on VPS","title":"Linux有問必答：如何在VPS上安裝和訪問CentOS 7遠程桌面","tag":"201505","desc":""},"relativePath":"201505/20150323 Linux FAQs with Answers--How to install and access CentOS remote desktop on VPS.md","filePath":"[post].md"}'),m={name:"201505/20150323 Linux FAQs with Answers--How to install and access CentOS remote desktop on VPS.md"};function u(C,e,S,V,x,c){const s=i("Link");return d(),a("div",null,[e[21]||(e[21]=n("h1",{id:"linux有問必答-如何在vps上安裝和訪問centos-7遠程桌面",tabindex:"-1"},[t("Linux有問必答：如何在VPS上安裝和訪問CentOS 7遠程桌面 "),n("a",{class:"header-anchor",href:"#linux有問必答-如何在vps上安裝和訪問centos-7遠程桌面","aria-label":"Permalink to “Linux有問必答：如何在VPS上安裝和訪問CentOS 7遠程桌面”"},"​")],-1)),e[22]||(e[22]=n("blockquote",null,[n("p",null,[n("strong",null,"提問"),t(": 我想在VPS中安裝CentOS桌面，並可以直接從我家遠程訪問GUI桌面。在VPS上設置和訪問CentOS遠程桌面有什麼建議嗎？")])],-1)),e[23]||(e[23]=n("p",null,"如何遠程辦公或者遠程彈性化工作制在技術領域正變得越來越流行。這個趨勢背後的一個技術就是遠程桌面。你的桌面環境在雲中，你可以在任何你去的地方，或者在家或者工作場所訪問你的遠程桌面。",-1)),e[24]||(e[24]=n("p",null,"這個教程介紹如何VPS中設置基於CentOS的遠程桌面。現在，我們會先展示CentOS的基礎環境。",-1)),n("p",null,[e[1]||(e[1]=t("我們假設你已經創建了CentOS 7的VPS實例（比如，使用",-1)),o(s,{href:"http://xmodulo.com/go/digitalocean"},{default:r(()=>[...e[0]||(e[0]=[t("DigitalOcean",-1)])]),_:1}),e[2]||(e[2]=t(" 或者 Amazon EC2）。請確保你的VPS實例有至少1GB的內存。不然，CentOS將會在你訪問遠程桌面的時候回崩潰。",-1))]),e[25]||(e[25]=n("h3",{id:"第一步-安裝centos桌面",tabindex:"-1"},[t("第一步： 安裝CentOS桌面 "),n("a",{class:"header-anchor",href:"#第一步-安裝centos桌面","aria-label":"Permalink to “第一步： 安裝CentOS桌面”"},"​")],-1)),n("p",null,[e[4]||(e[4]=t("如果你現在安裝的CentOS版本是沒有桌面的最小版本，你需要先在VPS上安裝桌面（比如GNOME）。比如，DigitalOcean的鏡像就是最小版本，它需要如下安裝",-1)),o(s,{href:"http://xmodulo.com/how-to-install-gnome-desktop-on-centos.html"},{default:r(()=>[...e[3]||(e[3]=[t("桌面GUI",-1)])]),_:1})]),e[26]||(e[26]=p(`<pre><code># yum groupinstall &quot;GNOME Desktop&quot; 
</code></pre><p>在安裝完成之後重啓VPS。</p><h3 id="第二步-安裝和配置vnc服務器" tabindex="-1">第二步：安裝和配置VNC服務器 <a class="header-anchor" href="#第二步-安裝和配置vnc服務器" aria-label="Permalink to “第二步：安裝和配置VNC服務器”">​</a></h3><p>接下來就是安裝和配置VNC服務器。我們使用的是TigerVNC,一個開源的VNC服務實現。</p><pre><code># yum install tigervnc-server 
</code></pre><p>現在創建一個用户賬户（比如：xmodulo）用來訪問遠程桌面。</p><pre><code># useradd xmodulo
# passwd xmodulo 
</code></pre><p>當一個用户嘗試使用VNC訪問遠程桌面時，VNC守護進程就會啓動來處理這個請求。這意味着你需要為每個用户創建一個獨立的VNC配置文件。</p><p>CentOS依靠systemd來管理和配置系統服務。所以我們將使用systemd來為用户xmodulo配置VNC服務器。</p><p>首先讓我們使用下面任意一條命令來檢查VNC服務器的狀態。</p><pre><code># systemctl status vncserver@:.service
# systemctl is-enabled vncserver@.service 
</code></pre><p>默認的，剛安裝的VNC服務並沒有激活(禁用)。</p><p><img src="https://farm8.staticflickr.com/7613/16877514732_8ccffe7b6b_b.jpg" alt=""></p><p>現在複製一份通用的VNC服務文件來為用户xmodulo創建一個VNC服務配置。</p><pre><code># cp /lib/systemd/system/vncserver@.service /etc/systemd/system/vncserver@:1.service 
</code></pre><p>用本文編輯器來打開配置文件，用實際的用户名（比如：xmodulo）來替換[Service]下面的<code>&lt;USER&gt;</code>。同樣。在ExecStart後面追加 <code>-geometry &lt;resolution&gt;</code> 參數。最後，要修改下面“ExecStart”和“PIDFile”兩行。</p><pre><code># vi /etc/systemd/system/vncserver@:1.service 
</code></pre><hr><pre><code>[Service]
Type=forking
# Clean any existing files in /tmp/.X11-unix environment
ExecStartPre=/bin/sh -c &#39;/usr/bin/vncserver -kill %i &gt; /dev/null 2&gt;&amp;1 || :&#39;
ExecStart=/sbin/runuser -l xmodulo -c &quot;/usr/bin/vncserver %i -geometry 1024x768&quot;
PIDFile=/home/xmodulo/.vnc/%H%i.pid
ExecStop=/bin/sh -c &#39;/usr/bin/vncserver -kill %i &gt; /dev/null 2&gt;&amp;1 || :&#39;
</code></pre><p>現在為用户xmodulo設置密碼（可選）。首先切換到該用户，並運行vncserver命令。</p><pre><code># su - xmodulo
# vncserver
</code></pre><p>你會被提示輸入用户的VNC密碼。密碼設置完成後，你下次需要用這個密碼來訪問你的遠程桌面。</p><p><img src="https://farm9.staticflickr.com/8752/16692564599_9c4e5da1b6_b.jpg" alt=""></p><p>最後，重新加載服務來使新的VNC配置生效：</p><pre><code># systemctl daemon-reload
</code></pre><p>在啓動時自動啓動VNC服務：</p><pre><code># systemctl enable vncserver@:1.service
</code></pre><p>檢查vnc服務正在監聽的端口：</p><pre><code># netstat -tulpn | grep vnc 
</code></pre><p><img src="https://farm8.staticflickr.com/7625/16692646729_7bb16c4897_b.jpg" alt=""></p><p>端口5901是VNC默認的客户端連接到VNC服務器使用的端口。</p><h3 id="第三步-通過ssh連接到遠程桌面" tabindex="-1">第三步：通過SSH連接到遠程桌面 <a class="header-anchor" href="#第三步-通過ssh連接到遠程桌面" aria-label="Permalink to “第三步：通過SSH連接到遠程桌面”">​</a></h3>`,32)),n("p",null,[e[6]||(e[6]=t("從設計上説，VNC使用的遠程幀緩存（RFB）並不是一種安全的協議，那麼在VNC客户端上直接連接到VNC服務器上並不是一個好主意。任何敏感信息比如密碼都可以在VNC流量中被輕易地泄露。因此，我強烈建議使用SSH隧道來",-1)),o(s,{href:"http://xmodulo.com/how-to-set-up-vnc-over-ssh.html"},{default:r(()=>[...e[5]||(e[5]=[t("加密你的VNC流量",-1)])]),_:1}),e[7]||(e[7]=t("。",-1))]),e[27]||(e[27]=p(`<p>在你要運行VNC客户端的本機上，使用下面的命令來創建一個連接到遠程VPS的SSH通道。當被要輸入SSH密碼時，輸入用户的密碼。</p><pre><code>$ ssh xmodulo@&lt;VPS-IP-address&gt; -L 5901:127.0.0.1:5901 
</code></pre><p>用你自己的VNC用户名來替換“xmodulo”，並填上你自己的VPS IP地址。</p><p>一旦SSH通道建立之後，遠程VNC流量就會通過ssh通道路由併發送到127.0.0.1:5901。</p><p>現在啓動你最愛的VNC客户端（比如：vinagre），來連接到127.0.0.1:5901。</p><p><img src="https://farm8.staticflickr.com/7639/16691289910_fae83510fb_o.png" alt=""></p><p>你將被要求輸入VNC密碼。當你輸入VNC密碼時，你就可以安全地連接到CentOS的遠程桌面了。</p><p><img src="https://farm8.staticflickr.com/7614/16877678411_aa8349f6b1_c.jpg" alt=""></p><p><img src="https://farm9.staticflickr.com/8702/16256320434_81f9b5b70c_c.jpg" alt=""></p><hr>`,10)),n("p",null,[e[9]||(e[9]=t("via: ",-1)),o(s,{href:"http://ask.xmodulo.com/centos-remote-desktop-vps.html"},{default:r(()=>[...e[8]||(e[8]=[t("http://ask.xmodulo.com/centos-remote-desktop-vps.html",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=t("作者：",-1)),o(s,{href:"http://ask.xmodulo.com/author/nanni"},{default:r(()=>[...e[10]||(e[10]=[t("Dan Nanni",-1)])]),_:1}),e[14]||(e[14]=t(" 譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:r(()=>[...e[11]||(e[11]=[t("geekpi",-1)])]),_:1}),e[15]||(e[15]=t(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...e[12]||(e[12]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[18]||(e[18]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[16]||(e[16]=[t("LCTT",-1)])]),_:1}),e[19]||(e[19]=t(" 原創翻譯，",-1)),o(s,{href:"http://linux.cn/"},{default:r(()=>[...e[17]||(e[17]=[t("Linux中國",-1)])]),_:1}),e[20]||(e[20]=t(" 榮譽推出",-1))])])}const N=l(m,[["render",u]]);export{g as __pageData,N as default};
